        separation?: number;
        alignment?: number;
        cohesion?: number;
        useRelativeParameters?: boolean;
        debug?: boolean;
        useDirection?: boolean;
        useMatrices?: boolean;
        timeScale?: number;
        fixedTimeStep?: number | null;
        maxSubsteps?: number;
        maxFrameDelta?: number;
        useSpatialGrid?: boolean;
